const boxes=[...document.querySelectorAll('[data-stop]')],key='frolicking-nicky-bratislava-v1';let state={};try{state=JSON.parse(localStorage.getItem(key)||'{}')||{}}catch{}for(const box of boxes)box.checked=state[box.dataset.stop]===true;function update(){const done=boxes.filter(b=>b.checked).length;document.querySelector('#vn-count').textContent=done+' / '+boxes.length+' completed';const progress=document.querySelector('#vn-progress');progress.max=boxes.length;progress.value=done}function save(){const data=Object.fromEntries(boxes.map(b=>[b.dataset.stop,b.checked]));try{localStorage.setItem(key,JSON.stringify(data));document.querySelector('#vn-save').textContent='Your ticks stay on this device.'}catch{document.querySelector('#vn-save').textContent='Saving is unavailable; ticks work until you leave this page.'}update()}boxes.forEach(b=>b.addEventListener('change',save));document.querySelector('.vn-reset').addEventListener('click',()=>{if(confirm('Clear your Bratislava checklist?')){boxes.forEach(b=>b.checked=false);save()}});update();